# CodexDrop: Windows PowerShell 5.1 drop window that sends saved image files to
# one confirmed, already running Codex chat over the existing nested SSH route
# (work WSL -> bastion -> home). Generated by `codex-drop bundle`; the two
# placeholders below are replaced exactly once. Keep this file ASCII-only.
# It never presses Enter, never writes the clipboard and never changes keys,
# profiles or execution policy.
Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$ClientB64 = '__CODEX_DROP_CLIENT_B64__'
$ConfigB64 = '__CODEX_DROP_CONFIG_B64__'

if ($ClientB64.StartsWith('__CODEX_DROP_') -or $ConfigB64.StartsWith('__CODEX_DROP_')) {
    [void][System.Windows.Forms.MessageBox]::Show(
        'This is the unbundled template. Generate it with: codex-drop bundle', 'Codex Drop')
    exit 1
}

$Utf8 = New-Object System.Text.UTF8Encoding($false)
$Config = $Utf8.GetString([Convert]::FromBase64String($ConfigB64)) | ConvertFrom-Json
$ClientBytes = [Convert]::FromBase64String($ClientB64)
$MaxImage = 25MB
$MaxBatch = 50MB
$MaxFiles = 10
$MaxRequest = 80MB
$ImageExtensions = @('.png', '.jpg', '.jpeg', '.gif', '.webp')
# Fixed loader: reads the framed client source from stdin and runs it. Contains
# no double quotes or backslashes so Windows argument parsing keeps it intact.
$Stub = "import sys;r=sys.stdin.buffer;n=int.from_bytes(r.read(4),'big');exec(compile(r.read(n),'codex-drop','exec'))"

$script:Queue = New-Object System.Collections.ArrayList
$script:Job = $null
$script:PendingToken = $null
$script:ConfirmedToken = $null
$script:PendingText = ''

# --- helpers -----------------------------------------------------------------

function Get-Prop($Object, [string]$Name) {
    if ($null -eq $Object) { return $null }
    $property = $Object.PSObject.Properties[$Name]
    if ($property) { return $property.Value }
    return $null
}

function ConvertTo-JsonText([string]$Text) {
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append('"')
    foreach ($ch in $Text.ToCharArray()) {
        $code = [int]$ch
        if ($ch -eq '"' -or $ch -eq '\') {
            [void]$builder.Append('\').Append($ch)
        } elseif ($code -lt 32 -or $code -gt 126) {
            [void]$builder.Append('\u').Append($code.ToString('x4'))
        } else {
            [void]$builder.Append($ch)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function Get-Sha256Hex([byte[]]$Bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        return -join ($sha.ComputeHash($Bytes) | ForEach-Object { $_.ToString('x2') })
    } finally {
        $sha.Dispose()
    }
}

function Get-ImageKind([byte[]]$Bytes) {
    if ($Bytes.Length -ge 8 -and $Bytes[0] -eq 0x89 -and $Bytes[1] -eq 0x50 -and $Bytes[2] -eq 0x4E -and
        $Bytes[3] -eq 0x47 -and $Bytes[4] -eq 0x0D -and $Bytes[5] -eq 0x0A -and $Bytes[6] -eq 0x1A -and
        $Bytes[7] -eq 0x0A) { return 'png' }
    if ($Bytes.Length -ge 3 -and $Bytes[0] -eq 0xFF -and $Bytes[1] -eq 0xD8 -and $Bytes[2] -eq 0xFF) {
        return 'jpg'
    }
    if ($Bytes.Length -ge 6) {
        $head = [System.Text.Encoding]::ASCII.GetString($Bytes, 0, 6)
        if ($head -ceq 'GIF87a' -or $head -ceq 'GIF89a') { return 'gif' }
    }
    if ($Bytes.Length -ge 12 -and [System.Text.Encoding]::ASCII.GetString($Bytes, 0, 4) -ceq 'RIFF' -and
        [System.Text.Encoding]::ASCII.GetString($Bytes, 8, 4) -ceq 'WEBP') { return 'webp' }
    return $null
}

function Read-ImageBytes([string]$Path) {
    $stream = [System.IO.FileStream]::new($Path, [System.IO.FileMode]::Open,
        [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
    try {
        $length = $stream.Length
        if ($length -le 0 -or $length -gt $MaxImage) {
            throw 'Image is empty or over the 25 MiB limit'
        }
        $bytes = [byte[]]::new([int]$length)
        $offset = 0
        while ($offset -lt $bytes.Length) {
            $count = $stream.Read($bytes, $offset, $bytes.Length - $offset)
            if ($count -eq 0) { throw 'Image length changed while reading' }
            $offset += $count
        }
        $extra = [byte[]]::new(1)
        if ($stream.Read($extra, 0, 1) -ne 0 -or $stream.Length -ne $length) {
            throw 'Image length changed while reading'
        }
        return ,$bytes
    } finally {
        $stream.Dispose()
    }
}

function Write-Ascii([System.IO.MemoryStream]$Stream, [string]$Text) {
    $bytes = [System.Text.Encoding]::ASCII.GetBytes($Text)
    $Stream.Write($bytes, 0, $bytes.Length)
}

function Write-Length([System.IO.MemoryStream]$Stream, [long]$Length) {
    $n = [uint32]$Length
    $header = [byte[]]@((($n -shr 24) -band 0xFF), (($n -shr 16) -band 0xFF),
                        (($n -shr 8) -band 0xFF), ($n -band 0xFF))
    $Stream.Write($header, 0, 4)
}

# stdin = [len][client source][len][request JSON]; returns the MemoryStream.
function New-StdinPayload([string]$Op, [string]$Token, [object[]]$Images) {
    $ms = New-Object System.IO.MemoryStream
    Write-Length $ms $ClientBytes.Length
    $ms.Write($ClientBytes, 0, $ClientBytes.Length)
    $lengthAt = $ms.Position
    Write-Length $ms 0
    $start = $ms.Position
    Write-Ascii $ms ('{"version":1,"op":' + (ConvertTo-JsonText $Op) +
        ',"thread":' + (ConvertTo-JsonText ([string]$Config.thread)) +
        ',"socket":' + (ConvertTo-JsonText ([string]$Config.socket)) +
        ',"bastion":' + (ConvertTo-JsonText ([string]$Config.bastion)) +
        ',"home":' + (ConvertTo-JsonText ([string]$Config.home)))
    if ($Op -eq 'upload') {
        Write-Ascii $ms (',"attach":true,"target_token":' + (ConvertTo-JsonText $Token) + ',"images":[')
        $first = $true
        foreach ($image in $Images) {
            if (-not $first) { Write-Ascii $ms ',' }
            $first = $false
            Write-Ascii $ms ('{"name":' + (ConvertTo-JsonText $image.Name) + ',"size":' + $image.Size +
                ',"sha256":"' + $image.Sha256 + '","data":"')
            Write-Ascii $ms ([Convert]::ToBase64String($image.Bytes))
            Write-Ascii $ms '"}'
        }
        Write-Ascii $ms ']'
    }
    Write-Ascii $ms '}'
    $requestLength = $ms.Position - $start
    if ($requestLength -gt $MaxRequest) { throw 'Request is larger than the protocol limit' }
    $ms.Position = $lengthAt
    Write-Length $ms $requestLength
    $ms.Position = $ms.Length
    return $ms
}

# --- UI ------------------------------------------------------------------------

[System.Windows.Forms.Application]::EnableVisualStyles()
$form = New-Object System.Windows.Forms.Form
$form.Text = 'Codex Drop - thread ' + ([string]$Config.thread).Substring(0, 8)
$form.Size = New-Object System.Drawing.Size(600, 560)
$form.StartPosition = 'CenterScreen'
$form.MinimumSize = New-Object System.Drawing.Size(520, 480)

$targetLabel = New-Object System.Windows.Forms.Label
$targetLabel.Location = New-Object System.Drawing.Point(10, 10)
$targetLabel.Size = New-Object System.Drawing.Size(565, 78)
$targetLabel.Anchor = 'Top,Left,Right'
$targetLabel.BorderStyle = 'FixedSingle'
$targetLabel.Text = 'Target: not confirmed. Click Refresh target.'

$buttonTest = New-Object System.Windows.Forms.Button
$buttonTest.Text = 'Test route'
$buttonTest.Location = New-Object System.Drawing.Point(10, 95)
$buttonTest.Size = New-Object System.Drawing.Size(105, 28)

$buttonRefresh = New-Object System.Windows.Forms.Button
$buttonRefresh.Text = 'Refresh target'
$buttonRefresh.Location = New-Object System.Drawing.Point(120, 95)
$buttonRefresh.Size = New-Object System.Drawing.Size(105, 28)

$buttonConfirm = New-Object System.Windows.Forms.Button
$buttonConfirm.Text = 'Use this chat'
$buttonConfirm.Location = New-Object System.Drawing.Point(230, 95)
$buttonConfirm.Size = New-Object System.Drawing.Size(105, 28)

$buttonSend = New-Object System.Windows.Forms.Button
$buttonSend.Text = 'Send queued'
$buttonSend.Location = New-Object System.Drawing.Point(340, 95)
$buttonSend.Size = New-Object System.Drawing.Size(105, 28)

$buttonClear = New-Object System.Windows.Forms.Button
$buttonClear.Text = 'Clear queue'
$buttonClear.Location = New-Object System.Drawing.Point(450, 95)
$buttonClear.Size = New-Object System.Drawing.Size(105, 28)

$checkAuto = New-Object System.Windows.Forms.CheckBox
$checkAuto.Text = 'Send on drop (to the confirmed chat only)'
$checkAuto.Checked = $true
$checkAuto.Location = New-Object System.Drawing.Point(10, 128)
$checkAuto.Size = New-Object System.Drawing.Size(400, 22)

$dropLabel = New-Object System.Windows.Forms.Label
$dropLabel.Location = New-Object System.Drawing.Point(10, 153)
$dropLabel.Size = New-Object System.Drawing.Size(565, 90)
$dropLabel.Anchor = 'Top,Left,Right'
$dropLabel.BorderStyle = 'FixedSingle'
$dropLabel.TextAlign = 'MiddleCenter'
$dropLabel.AllowDrop = $true
$dropLabel.Text = "Drop saved PNG / JPEG / GIF / WebP files here`r`n(Enter is never pressed: review the Codex composer and send it yourself)"

$queueList = New-Object System.Windows.Forms.ListBox
$queueList.Location = New-Object System.Drawing.Point(10, 250)
$queueList.Size = New-Object System.Drawing.Size(565, 80)
$queueList.Anchor = 'Top,Left,Right'

$progress = New-Object System.Windows.Forms.ProgressBar
$progress.Location = New-Object System.Drawing.Point(10, 335)
$progress.Size = New-Object System.Drawing.Size(565, 14)
$progress.Anchor = 'Top,Left,Right'
$progress.Style = 'Marquee'
$progress.MarqueeAnimationSpeed = 0
$progress.Visible = $false

$statusBox = New-Object System.Windows.Forms.TextBox
$statusBox.Location = New-Object System.Drawing.Point(10, 355)
$statusBox.Size = New-Object System.Drawing.Size(565, 155)
$statusBox.Anchor = 'Top,Bottom,Left,Right'
$statusBox.Multiline = $true
$statusBox.ReadOnly = $true
$statusBox.ScrollBars = 'Vertical'

$form.Controls.AddRange(@($targetLabel, $buttonTest, $buttonRefresh, $buttonConfirm, $buttonSend,
    $buttonClear, $checkAuto, $dropLabel, $queueList, $progress, $statusBox))

$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 200

function Write-Status([string]$Text) {
    $statusBox.AppendText((Get-Date).ToString('HH:mm:ss') + '  ' + $Text + "`r`n")
}

function Update-QueueList {
    $queueList.Items.Clear()
    foreach ($item in $script:Queue) {
        [void]$queueList.Items.Add(('{0}  ({1:N0} KB)  queued' -f $item.Name, [math]::Ceiling($item.Size / 1KB)))
    }
}

function Update-Controls {
    $busy = $null -ne $script:Job
    $buttonTest.Enabled = -not $busy
    $buttonRefresh.Enabled = -not $busy
    $buttonConfirm.Enabled = (-not $busy) -and ($null -ne $script:PendingToken)
    $buttonSend.Enabled = (-not $busy) -and ($null -ne $script:ConfirmedToken) -and ($script:Queue.Count -gt 0)
    $buttonClear.Enabled = (-not $busy) -and ($script:Queue.Count -gt 0)
    $progress.Visible = $busy
    $progress.MarqueeAnimationSpeed = $(if ($busy) { 30 } else { 0 })
}

function Get-ErrorText($Reply, [string]$ErrText) {
    $failure = Get-Prop $Reply 'error'
    if ($failure) { return ('{0}: {1}' -f (Get-Prop $failure 'code'), (Get-Prop $failure 'message')) }
    if ($ErrText) { return ('no reply from client. ' + $ErrText.Trim()) }
    return 'no reply from client (is python3 available in the default WSL distribution?)'
}

# Child process: hidden wsl.exe, stdin written asynchronously, polled by a timer.
function Start-Client([System.IO.MemoryStream]$Payload, [string]$Label, [int]$TimeoutSeconds,
                      [scriptblock]$OnDone, $Context) {
    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = 'wsl.exe'
    $psi.Arguments = '-e python3 -I -c "' + $Stub + '" client'
    $psi.UseShellExecute = $false
    $psi.CreateNoWindow = $true
    $psi.RedirectStandardInput = $true
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.StandardOutputEncoding = $Utf8
    $psi.StandardErrorEncoding = $Utf8
    try {
        $proc = [System.Diagnostics.Process]::Start($psi)
    } catch {
        Write-Status ('Cannot start wsl.exe: ' + $_.Exception.Message)
        return
    }
    $script:Job = @{
        Process = $proc
        Out = $proc.StandardOutput.ReadToEndAsync()
        Err = $proc.StandardError.ReadToEndAsync()
        Write = $proc.StandardInput.BaseStream.WriteAsync($Payload.GetBuffer(), 0, [int]$Payload.Length)
        Payload = $Payload
        InputClosed = $false
        TimedOut = $false
        Deadline = (Get-Date).AddSeconds($TimeoutSeconds)
        OnDone = $OnDone
        Context = $Context
    }
    Write-Status $Label
    Update-Controls
    $timer.Start()
}

function Complete-Job($Job) {
    $outText = ''
    $errText = ''
    try { $outText = [string]$Job.Out.Result } catch { }
    try { $errText = [string]$Job.Err.Result } catch { }
    $Job.Payload.Dispose()
    $reply = $null
    $lines = @($outText -split "`n" | Where-Object { $_.Trim() })
    if ($lines.Count -gt 0) {
        try { $reply = $lines[$lines.Count - 1] | ConvertFrom-Json } catch { $reply = $null }
    }
    if ($Job.TimedOut) {
        $reply = $null
        $checkAuto.Checked = $false
        $errText = 'Timed out; result uncertain. ' + $errText
    }
    if ($errText.Length -gt 400) { $errText = $errText.Substring($errText.Length - 400) }
    & $Job.OnDone $reply $errText $Job.Context
    Update-Controls
}

$timer.Add_Tick({
    $job = $script:Job
    if ($null -eq $job) { $timer.Stop(); return }
    if (-not $job.InputClosed -and $job.Write.IsCompleted) {
        try { $job.Process.StandardInput.Close() } catch { }
        $job.InputClosed = $true
    }
    if ($job.Process.HasExited -and $job.Out.IsCompleted -and $job.Err.IsCompleted) {
        $timer.Stop()
        $script:Job = $null
        Complete-Job $job
        return
    }
    if (-not $job.TimedOut -and (Get-Date) -gt $job.Deadline) {
        $job.TimedOut = $true
        $checkAuto.Checked = $false
        try { $job.Process.Kill() } catch { }
    }
})

# --- operations ----------------------------------------------------------------

function Show-Target($Target, [string]$Composer, [bool]$Confirmed) {
    $state = $(if ($Confirmed) { 'CONFIRMED target' } else { 'Found target (click "Use this chat" to confirm)' })
    $targetLabel.Text = ('{0}: {1}' -f $state, (Get-Prop $Target 'window_name')) + "`r`n" +
        ('Session {0}, pane {1}, window {2}' -f (Get-Prop $Target 'session'), (Get-Prop $Target 'pane'),
            (Get-Prop $Target 'window')) + "`r`n" +
        ('Codex pid {0} (start {1}), thread {2}' -f (Get-Prop $Target 'tui_pid'),
            (Get-Prop $Target 'tui_start'), (Get-Prop $Target 'thread')) + "`r`n" +
        ('Composer: {0}' -f $Composer)
}

function Clear-Confirmation([string]$Why) {
    $script:ConfirmedToken = $null
    $targetLabel.Text = 'Target: not confirmed (' + $Why + '). Click Refresh target.'
}

function Start-TestRoute {
    if ($script:Job) { return }
    Start-Client (New-StdinPayload 'test_route' '' @()) 'Testing route work WSL -> bastion -> home...' 150 {
        param($Reply, $ErrText, $Context)
        if ((Get-Prop $Reply 'ok') -eq $true) {
            Write-Status ('Route OK (' + (Get-Prop $Reply 'route') + '); home receiver ready.')
        } else {
            Write-Status ('Route FAILED: ' + (Get-ErrorText $Reply $ErrText))
        }
    } $null
}

function Start-RefreshTarget {
    if ($script:Job) { return }
    $script:PendingToken = $null
    Start-Client (New-StdinPayload 'target' '' @()) 'Looking up the live Codex chat (read-only)...' 120 {
        param($Reply, $ErrText, $Context)
        if ((Get-Prop $Reply 'ok') -eq $true) {
            $script:ConfirmedToken = $null
            $script:PendingToken = [string](Get-Prop $Reply 'target_token')
            $script:PendingTarget = Get-Prop $Reply 'target'
            $script:PendingComposer = [string](Get-Prop $Reply 'composer')
            Show-Target $script:PendingTarget $script:PendingComposer $false
            Write-Status 'Target found. Check the chat title, then click "Use this chat".'
        } else {
            Clear-Confirmation 'lookup failed'
            Write-Status ('Target lookup FAILED: ' + (Get-ErrorText $Reply $ErrText))
        }
    } $null
}

function Add-QueueFile([string]$Path) {
    if (Test-Path -LiteralPath $Path -PathType Container) {
        Write-Status ('Skipped folder: ' + $Path); return
    }
    $info = New-Object System.IO.FileInfo($Path)
    if (-not $info.Exists) { Write-Status ('Skipped missing file: ' + $Path); return }
    if ($ImageExtensions -notcontains $info.Extension.ToLowerInvariant()) {
        Write-Status ('Skipped (not PNG/JPEG/GIF/WebP): ' + $info.Name); return
    }
    if ($info.Length -le 0 -or $info.Length -gt $MaxImage) {
        Write-Status ('Skipped (empty or over 25 MB): ' + $info.Name); return
    }
    foreach ($item in $script:Queue) {
        if ($item.Path -eq $info.FullName) { return }
    }
    if ($script:Queue.Count -ge $MaxFiles) {
        Write-Status ('Queue full (10 files); skipped ' + $info.Name); return
    }
    [void]$script:Queue.Add([pscustomobject]@{ Path = $info.FullName; Name = $info.Name; Size = $info.Length })
}

function Start-Upload {
    if ($script:Job) { return }
    if (-not $script:ConfirmedToken) { Write-Status 'Confirm a target first (Refresh target, then Use this chat).'; return }
    $batch = New-Object System.Collections.ArrayList
    $total = 0
    foreach ($item in @($script:Queue)) {
        if ($batch.Count -ge $MaxFiles) { break }
        try {
            $bytes = Read-ImageBytes $item.Path
        } catch {
            Write-Status ('Cannot read ' + $item.Name + ': ' + $_.Exception.Message)
            $script:Queue.Remove($item); continue
        }
        if ($bytes.Length -le 0 -or $bytes.Length -gt $MaxImage) {
            Write-Status ('Skipped (empty or over 25 MB): ' + $item.Name); $script:Queue.Remove($item); continue
        }
        if (-not (Get-ImageKind $bytes)) {
            Write-Status ('Skipped (content is not PNG/JPEG/GIF/WebP): ' + $item.Name)
            $script:Queue.Remove($item); continue
        }
        if ($total + $bytes.Length -gt $MaxBatch) { break }
        $total += $bytes.Length
        [void]$batch.Add([pscustomobject]@{ Item = $item; Name = $item.Name; Size = $bytes.Length;
            Sha256 = (Get-Sha256Hex $bytes); Bytes = $bytes })
    }
    Update-QueueList
    if ($batch.Count -eq 0) { Update-Controls; return }
    try {
        $payload = New-StdinPayload 'upload' $script:ConfirmedToken $batch.ToArray()
    } catch {
        Write-Status ('Cannot build upload: ' + $_.Exception.Message); return
    }
    $sent = @($batch | ForEach-Object { $_.Item })
    $batch = $null
    Start-Client $payload ('Uploading ' + $sent.Count + ' image(s)...') 900 {
        param($Reply, $ErrText, $Context)
        Complete-Upload $Reply $ErrText $Context
    } $sent
}

function Complete-Upload($Reply, [string]$ErrText, $Sent) {
    if ((Get-Prop $Reply 'ok') -ne $true) {
        $checkAuto.Checked = $false
        $code = Get-Prop (Get-Prop $Reply 'error') 'code'
        Write-Status ('Upload FAILED: ' + (Get-ErrorText $Reply $ErrText))
        if ($null -eq $Reply -or $code -eq 'timeout') {
            Write-Status 'Result uncertain: check the Codex composer before sending again (no automatic retry).'
        }
        if ($code -in @('bad_target', 'target_changed', 'target_missing', 'target_not_codex')) {
            Clear-Confirmation 'target changed'
        }
        return
    }
    foreach ($item in $Sent) { $script:Queue.Remove($item) }
    Update-QueueList
    foreach ($file in @(Get-Prop $Reply 'files')) {
        Write-Status ('  {0}: saved on home ({1:N0} bytes, sha256 {2}...), attach: {3}' -f
            (Get-Prop $file 'name'), (Get-Prop $file 'size'),
            ([string](Get-Prop $file 'sha256')).Substring(0, 12), (Get-Prop $file 'attach'))
    }
    $attach = Get-Prop $Reply 'attach'
    if ((Get-Prop $Reply 'status') -eq 'transferred+attached-verified') {
        Write-Status 'DONE: transferred and attachment verified in Codex. Review the composer and press Enter yourself.'
    } else {
        Write-Status ('TRANSFERRED ONLY: attachment NOT verified - ' + (Get-Prop $attach 'message'))
        $checkAuto.Checked = $false
        if ((Get-Prop $attach 'code') -in @('target_changed', 'target_missing', 'target_not_codex')) {
            Clear-Confirmation 'target changed'
        }
    }
}

# --- events --------------------------------------------------------------------

$buttonTest.Add_Click({ Start-TestRoute })
$buttonRefresh.Add_Click({ Start-RefreshTarget })
$buttonConfirm.Add_Click({
    if ($null -eq $script:PendingToken) { return }
    $script:ConfirmedToken = $script:PendingToken
    Show-Target $script:PendingTarget $script:PendingComposer $true
    Write-Status 'Target confirmed. Dropped images will be attached to this chat only.'
    Update-Controls
    if ($checkAuto.Checked -and $script:Queue.Count -gt 0) { Start-Upload }
})
$buttonSend.Add_Click({ Start-Upload })
$buttonClear.Add_Click({ $script:Queue.Clear(); Update-QueueList; Update-Controls })

$dropLabel.Add_DragEnter({
    param($src, $ea)
    if ($ea.Data.GetDataPresent([System.Windows.Forms.DataFormats]::FileDrop)) {
        $ea.Effect = [System.Windows.Forms.DragDropEffects]::Copy
    } else {
        $ea.Effect = [System.Windows.Forms.DragDropEffects]::None
        Write-Status 'This drag is not a saved file (browser/Outlook images are virtual). Save the image first, then drag the saved file.'
    }
})
$dropLabel.Add_DragDrop({
    param($src, $ea)
    $paths = [string[]]$ea.Data.GetData([System.Windows.Forms.DataFormats]::FileDrop)
    foreach ($path in $paths) { Add-QueueFile $path }
    Update-QueueList
    Update-Controls
    if ($checkAuto.Checked -and $script:ConfirmedToken -and -not $script:Job) { Start-Upload }
})

$form.Add_FormClosing({
    param($src, $ea)
    if ($script:Job) {
        $answer = [System.Windows.Forms.MessageBox]::Show(
            'An operation is still running. Closing stops it and the result may be uncertain. Close anyway?',
            'Codex Drop', 'YesNo', 'Warning')
        if ($answer -ne 'Yes') { $ea.Cancel = $true; return }
        try { $script:Job.Process.Kill() } catch { }
    }
    $timer.Stop()
})
$form.Add_Shown({ Start-RefreshTarget })

$script:PendingTarget = $null
$script:PendingComposer = ''
Update-Controls
[System.Windows.Forms.Application]::Run($form)
